content.content:
1	// Module intake, key: the order id. Owns R1.1 (allocate and record within 60 min of placedAt), R1.2 (amounts and
2	// fees), R1.3 (the edition in force at placedAt, fixed for the life of the order) and R1.4 (a placed order already
3	// recorded is a duplicate: no effect). Effects: inventory.allocate (key 'allocate'), orders.create (key 'create').
4	// Always returns `output`.
5	
6	const MIN = 60000;
7	
8	function lastSunday(y, m) {
9	  const last = new Date(Date.UTC(y, m + 1, 0));
10	  return last.getUTCDate() - last.getUTCDay();
11	}
12	
13	function amsOffsetMin(ms) {
14	  const y = new Date(ms).getUTCFullYear();
15	  const start = Date.UTC(y, 2, lastSunday(y, 2), 1);
16	  const end = Date.UTC(y, 9, lastSunday(y, 9), 1);
17	  return ms >= start && ms < end ? 120 : 60;
18	}
19	
20	// The calendar date of an instant in Europe/Amsterdam, YYYY-MM-DD.
21	function amsDate(ms) {
22	  const d = new Date(ms + amsOffsetMin(ms) * MIN);
23	  const p = n => String(n).padStart(2, '0');
24	  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}`;
25	}
26	
27	function readJson(files, path) {
28	  let v = files?.[path];
29	  if (v === undefined) { v = files; for (const seg of path.split('/')) v = v?.[seg]; }
30	  if (typeof v === 'string') return JSON.parse(v);
31	  return v ?? null;
32	}
33	
34	// Rows of a master or rulebook table, whether it is an array, an object holding an array, or a map keyed by id.
35	function rowsOf(x) {
36	  if (Array.isArray(x)) return x;
37	  if (x && typeof x === 'object') {
38	    const arr = Object.values(x).find(v => Array.isArray(v));
39	    if (arr) return arr;
40	    return Object.entries(x).map(([k, v]) => (v && typeof v === 'object' ? { key: k, ...v } : { key: k, value: v }));
41	  }
42	  return [];
43	}
44	
45	function editionDirs(files) {
46	  const dirs = new Set();
47	  for (const k of Object.keys(files ?? {})) {
48	    const m = /^rulebook\/([^/]+)\/edition\.json$/.exec(k);
49	    if (m) dirs.add(m[1]);
50	  }
51	  if (dirs.size === 0 && files?.rulebook && typeof files.rulebook === 'object') {
52	    for (const k of Object.keys(files.rulebook)) if (files.rulebook[k]?.['edition.json'] !== undefined) dirs.add(k);
53	  }
54	  return [...dirs];
55	}
56	
57	// R1.3: the published edition with the latest effectiveFrom on or before the Amsterdam date of placedAt.
58	function editionAt(files, placedAt) {
59	  const day = amsDate(Date.parse(placedAt));
60	  let best = null;
61	  for (const dir of editionDirs(files)) {
62	    const e = readJson(files, `rulebook/${dir}/edition.json`);
63	    if (!e || typeof e.effectiveFrom !== 'string' || e.effectiveFrom > day) continue;
64	    if (!best || e.effectiveFrom > best.from) best = { dir, from: e.effectiveFrom };
65	  }
66	  if (!best) throw new Error(`no edition in force at ${placedAt}`);
67	  return best.dir;
68	}
69	
70	function priceOf(files, sku) {
71	  const r = rowsOf(readJson(files, 'master/catalog.json')).find(x => (x.sku ?? x.key) === sku);
72	  if (!r || typeof r.unitPriceMinor !== 'number') throw new Error(`no unit price for ${sku}`);
73	  return r.unitPriceMinor;
74	}
75	
76	function feeOf(files, edition, location) {
77	  const r = rowsOf(readJson(files, `rulebook/${edition}/shipping-fees.json`)).find(x => (x.location ?? x.key) === location);
78	  const fee = r?.feeMinor ?? r?.value;
79	  if (typeof fee !== 'number') throw new Error(`no shipping fee for ${location} in ${edition}`);
80	  return fee;
81	}
82	
83	// R1.2: Σ qty × unit price, plus the location's fee when the fulfilment has a location.
84	function amountOf(files, edition, f) {
85	  const goods = f.items.reduce((sum, it) => sum + it.qty * priceOf(files, it.sku), 0);
86	  return f.location === null ? goods : goods + feeOf(files, edition, f.location);
87	}
88	
89	function outOf(st, duplicate) {
90	  const plan = st && st.status !== 'new' ? {
91	    orderId: st.order.orderId,
92	    customerId: st.order.customerId,
93	    placedAt: st.order.placedAt,
94	    currency: st.order.currency,
95	    edition: st.edition,
96	    totalMinor: st.totalMinor,
97	    fulfilments: st.fulfilments ?? [],
98	  } : {};
99	  const output = { status: st?.status ?? 'new', duplicate, busy: !!st && Object.keys(st.inflight ?? {}).length > 0 };
100	  for (const [k, v] of Object.entries(plan)) if (v !== null && v !== undefined && !(Array.isArray(v) && v.length === 0)) output[k] = v;
101	  return { output };
102	}
103	
104	function fitEffect(e, ctx) {
105	  return { ...e, args: fit(e.system, e.op, e.args, ctx) };
106	}
107	
108	function createEffect(st) {
109	  return {
110	    key: 'create', system: 'orders', op: 'create',
111	    args: {
112	      orderId: st.order.orderId,
113	      customerId: st.order.customerId,
114	      placedAt: st.order.placedAt,
115	      currency: st.order.currency,
116	      items: st.order.items,
117	      fulfilments: st.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, location: f.location, items: f.items, amountMinor: f.amountMinor })),
118	      totalMinor: st.totalMinor,
119	    },
120	  };
121	}
122	
123	// The API may rename a field during the run; api/<system>.schema.json in ctx.files always shows the current names
124	// (SPEC-E §4.2). An argument the current schema no longer names moves to the single property that replaces it.
125	function fit(system, op, args, ctx) {
126	  const schema = readJson(ctx.files, `api/${system}.schema.json`);
127	  const a = schema?.ops?.[op]?.args;
128	  if (!a || !a.properties || !args) return args;
129	  const props = Object.keys(a.properties);
130	  const out = { ...args };
131	  for (const k of Object.keys(args).filter(k => !props.includes(k))) {
132	    const free = props.filter(p => !(p in out));
133	    const req = free.filter(p => (a.required ?? []).includes(p));
134	    const pick = req.length === 1 ? req[0] : free.length === 1 ? free[0] : null;
135	    if (pick) { out[pick] = out[k]; delete out[k]; }
136	  }
137	  return out;
138	}
139	
140	export function step(input, ctx) {
141	  switch (input.op) {
142	    case 'placed': return placed(input, ctx);
143	    case 'resume': return resume(input, ctx);
144	  }
145	  throw new Error(`intake: unknown op ${input.op}`);
146	}
147	
148	export function onEvent(event, ctx) {
149	  const st = ctx.state;
150	  if (!st) return outOf(null, false);
151	  const p = event.payload ?? {};
152	  if (event.type !== 'effect.result') return outOf(st, false);
153	
154	  if (p.key === 'allocate' && st.status === 'allocating') {
155	    if (p.status !== 'ok') return outOf(st, false);                 // permanent failure: stays allocating
156	    const plan = p.result ?? p;
157	    const edition = editionAt(ctx.files, st.order.placedAt);
158	    const fulfilments = plan.fulfilments.map(f => {
159	      const available = f.location !== null && f.available !== false;
160	      const location = f.location;
161	      const item = { fulfilmentId: f.fulfilmentId, location, available, items: f.items };
162	      return { ...item, amountMinor: amountOf(ctx.files, edition, { items: f.items, location }) };
163	    });
164	    const totalMinor = fulfilments.reduce((sum, f) => sum + f.amountMinor, 0);
165	    const next = { ...st, status: 'recording', edition, fulfilments, totalMinor, inflight: { create: true } };
166	    return { ...outOf(next, false), state: next, effects: [fitEffect(createEffect(next), ctx)] };
167	  }
168	
169	  if (p.key === 'create' && st.status === 'recording') {
170	    if (p.status === 'ok') {
171	      const next = { ...st, status: 'recorded', inflight: {} };
172	      return { ...outOf(next, false), state: next };
173	    }
174	    if (p.error?.status === 400 || p.error?.code === 'invalid-args' || p.error?.code === 'field-renamed') {
175	      return { ...outOf(st, false), effects: [fitEffect(createEffect(st), ctx)] };   // our request was wrong: same key, same args, again
176	    }
177	    return outOf(st, false);
178	  }
179	  return outOf(st, false);
180	}
181	
182	function placed(input, ctx) {
183	  if (ctx.state) return outOf(ctx.state, true);                    // already placed in this instance: duplicate
184	  const orderId = ctx.call('order-id', 'n', { raw: input.order.orderId }).orderId;
185	  const recorded = ctx.query('orders.orders', { where: { orderId }, limit: 1 });
186	  if (recorded.length > 0) return outOf({ status: 'recorded', order: { orderId }, inflight: {} }, true);   // R1.4
187	  const order = { ...input.order, orderId };
188	  const st = { status: 'allocating', order, edition: null, fulfilments: [], totalMinor: null, inflight: { allocate: true } };
189	  return {
190	    ...outOf(st, false),
191	    state: st,
192	    effects: [fitEffect({ key: 'allocate', system: 'inventory', op: 'allocate', args: { orderId } }, ctx)],
193	  };
194	}
195	
196	function resume(input, ctx) {
197	  // §3.5: a migrated order that is already recorded keeps its plan.
198	  const r = input.records?.intake;
199	  if (!r) return outOf(null, false);
200	  const edition = editionAt(ctx.files, r.order.placedAt);
201	  const st = { status: 'recorded', order: r.order, edition, fulfilments: r.fulfilments, totalMinor: r.totalMinor, inflight: {} };
202	  return { ...outOf(st, false), state: st };
203	}
204

