1	// Parent orchestrator: routing and the order of the phases. Owns SPEC-E §1 (routing, subject, delivery order), §3.2,
2	// §3.3 (which carrier message goes where), §3.5 (migration), the §4 preamble (act inside each window, never twice),
3	// S5, S8, S9, S10 (same-instant knowledge: forward steps only at the end of a tick), S11, S12, S13 and S15. It emits no
4	// effects itself: every system is reached through a module.
5	//
6	// Parent state (JSON, the parent's carry):
7	//   { orderId, phase: 'new'|'intake'|'fraud'|'waiting'|'processing'|'ended', placedAt, customerId, currency, edition,
8	//     totalMinor, fulfilments: [{ fulfilmentId, location, available, items, amountMinor }], clearedAt, readyAt,
9	//     progressReady, started: {fid: true}, ended: {fid: 'completed'|'failed'}, outcome, held: [customer actions],
10	//     busy: {module:key: bool} }
11	
12	export function tick(input, ctx) {
13	  const st = input.state ?? newState();
14	  const events = input.events ?? [];
15	  let first = null;
16	  if (st.phase === 'new' && events.length) {
17	    first = routeFirst(events[0], input, st, ctx);
18	    if (first.merge) return { decisions: { subject: first.subject }, state: st, merge: { into: first.merge } };
19	    if (first.close) return finish(st, first.subject, true);
20	  }
21	  for (const ev of events.slice(first ? 1 : 0)) handle(ev, st, ctx, input);
22	  endOfTick(st, ctx);
23	  return finish(st, st.orderId ?? null, st.phase === 'ended' && !busyAny(st));
24	}
25	
26	function newState() {
27	  return { phase: 'new', orderId: null, placedAt: null, customerId: null, currency: null, edition: null, totalMinor: null,
28	    fulfilments: [], clearedAt: null, readyAt: null, progressReady: false, started: {}, ended: {}, outcome: null, held: [], busy: {} };
29	}
30	
31	function finish(st, subject, close) {
32	  const out = { decisions: { subject: subject ?? null }, state: st };
33	  if (close) out.close = true;
34	  return out;
35	}
36	
37	function busyAny(st) {
38	  return Object.values(st.busy).some(Boolean);
39	}
40	
41	function setBusy(st, mod, key, out) {
42	  if (out && typeof out.busy === 'boolean') st.busy[`${mod}:${key}`] = out.busy;
43	}
44	
45	// Every module call goes through here, so the busy flags are kept.
46	function callMod(st, ctx, mod, key, input) {
47	  const out = ctx.call(mod, key, input);
48	  setBusy(st, mod, key, out);
49	  return out;
50	}
51	
52	function normalise(raw, ctx) {
53	  return ctx.call('order-id', 'n', { raw: typeof raw === 'string' ? raw : null }).orderId;
54	}
55	
56	function inboundKind(ev) {
57	  if (ev.type === 'migration') return 'migration';
58	  if (ev.source === 'shop' || ev.type === 'order.placed') return 'placed';
59	  if (ev.source === 'customer-portal' || ev.type === 'customer.action') return 'action';
60	  if (ev.source === 'carrier' || ev.type === 'carrier.status') return 'carrier';
61	  return null;
62	}
63	
64	// Open instances of an order, other than this one (ctx.instances lists open instances by declared subject).
65	function openOthers(oid, self, ctx) {
66	  return ctx.instances({ subject: oid }).map(x => (typeof x === 'string' ? x : x.instance)).filter(x => x && x !== self);
67	}
68	
69	// §1 Routing: the first tick of an instance started by a message. merge is only allowed here.
70	function routeFirst(ev, input, st, ctx) {
71	  const kind = inboundKind(ev);
72	  const p = ev.payload ?? {};
73	  if (kind === 'placed') {
74	    const oid = normalise(p.orderId, ctx);
75	    const others = openOthers(oid, input.instance, ctx);
76	    if (others.length) return { merge: others[0], subject: oid };
77	    st.orderId = oid;
78	    st.phase = 'intake';
79	    st.placedAt = ev.at;
80	    st.customerId = p.customerId;
81	    st.currency = p.currency;
82	    const order = { orderId: oid, customerId: p.customerId, placedAt: ev.at, currency: p.currency, items: p.items };
83	    const r = callMod(st, ctx, 'intake', oid, { op: 'placed', order });
84	    if (r.duplicate) { st.phase = 'ended'; return { subject: oid, close: true }; }    // R1.4: nothing
85	    return { subject: oid };
86	  }
87	  if (kind === 'action') {
88	    const oid = normalise(p.orderRef, ctx);
89	    if (!oid) return { subject: null, close: true };
90	    const others = openOthers(oid, input.instance, ctx);
91	    if (others.length) return { merge: others[0], subject: oid };
92	    return { subject: oid, close: true };                                          // no open case: nothing (§3.2, S11)
93	  }
94	  if (kind === 'carrier') {
95	    const rows = ctx.query('orders.fulfilments', { where: { fulfilmentId: p.fulfilmentRef }, limit: 1 });
96	    if (!rows.length) return { subject: null, close: true };
97	    const oid = normalise(rows[0].orderId, ctx);
98	    const others = openOthers(oid, input.instance, ctx);
99	    if (others.length) return { merge: others[0], subject: oid };
100	    return { subject: oid, close: true };                                          // §3.3: changes nothing
101	  }
102	  if (kind === 'migration') return resumeMigration(ev, st, ctx);
103	  return { subject: null, close: true };
104	}
105	
106	function handle(ev, st, ctx, input) {
107	  const owner = ctx.ownerOf(ev);
108	  if (owner) {
109	    const out = ctx.deliver(ev);
110	    onOutput(owner.module, owner.key, out, st, ctx);
111	    return;
112	  }
113	  const kind = inboundKind(ev);
114	  if (kind === 'placed') {
115	    // a merged duplicate of the placed order (R1.4)
116	    callMod(st, ctx, 'intake', st.orderId, { op: 'placed', order: { orderId: st.orderId, customerId: ev.payload.customerId,
117	      placedAt: ev.at, currency: ev.payload.currency, items: ev.payload.items } });
118	  } else if (kind === 'action') {
119	    routeAction({ eventId: ev.id, action: ev.payload.action, at: ev.at }, st, ctx);
120	  } else if (kind === 'carrier') {
121	    const fid = ev.payload.fulfilmentRef;
122	    if (!st.fulfilments.some(f => f.fulfilmentId === fid)) return;                 // §3.3: unknown shipment: nothing
123	    const r = callMod(st, ctx, 'fulfilment', fid, { op: 'carrier', at: ev.at, message: {
124	      code: ev.payload.code, reportedAt: ev.payload.reportedAt, carrier: ev.payload.carrier ?? null, shipmentId: ev.payload.shipmentId ?? null } });
125	    onOutput('fulfilment', fid, r, st, ctx);
126	  }
127	}
128	
129	// A customer action by phase (R3.2, R6.2, R6.3, R6.4, S5, S8, S11, S12, S15).
130	function routeAction(act, st, ctx) {
131	  const oid = st.orderId;
132	  switch (st.phase) {
133	    case 'intake': st.held.push(act); return;                                      // the order is not recorded yet
134	    case 'fraud':
135	      if (act.action === 'cancel') customerCancel(act, 'not-cleared', st, ctx);     // R6.4
136	      else st.held.push(act);
137	      return;
138	    case 'waiting': {
139	      const r = callMod(st, ctx, 'customer-action', oid, { op: 'action', action: act.action, at: act.at });
140	      customerActionOut(r, st, ctx);
141	      return;
142	    }
143	    case 'processing':
144	      if (act.action === 'cancel') customerCancel(act, 'processing', st, ctx);     // R6.2, R6.3
145	      return;                                                                      // amend: nothing (S5)
146	    case 'ended':
147	      if (act.action === 'cancel') customerCancel(act, 'ended', st, ctx);          // R6.3: changes nothing
148	      return;
149	  }
150	}
151	
152	function customerCancel(act, phase, st, ctx) {
153	  const r = callMod(st, ctx, 'cancellation', st.orderId, { op: 'customer-cancel', orderId: st.orderId, at: act.at, eventId: act.eventId, phase });
154	  if (r.verdict === 'counts') st.phase = 'ended';
155	}
156	
157	// Held customer actions are routed in order when their phase is reached (S10: they keep their own times).
158	function drainHeld(st, ctx) {
159	  const held = st.held;
160	  st.held = [];
161	  for (const act of held) routeAction(act, st, ctx);
162	}
163	
164	function onOutput(mod, key, out, st, ctx) {
165	  setBusy(st, mod, key, out);
166	  switch (mod) {
167	    case 'intake':
168	      if (out.status === 'recorded' && st.phase === 'intake') recorded(out, st, ctx);
169	      return;
170	    case 'fraud':
171	      fraudOut(out, st, ctx);
172	      return;
173	    case 'customer-action':
174	      customerActionOut(out, st, ctx);
175	      return;
176	    case 'fulfilment':
177	      fulfilmentOut(key, out, st, ctx);
178	      return;
179	    case 'order-progress':
180	      orderProgressOut(out, st);
181	      return;
182	    default:
183	      return;                                  // statuses, notices: busy flags only
184	  }
185	}
186	
187	// The order is recorded (R1.1): statuses and notices start, the fraud phase starts (R2.1).
188	function recorded(out, st, ctx) {
189	  const oid = st.orderId;
190	  st.edition = out.edition;
191	  st.totalMinor = out.totalMinor;
192	  st.fulfilments = out.fulfilments;
193	  st.phase = 'fraud';
194	  callMod(st, ctx, 'statuses', oid, { op: 'init', fulfilments: out.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, location: f.location })) });
195	  callMod(st, ctx, 'notices', oid, { op: 'init', customerId: st.customerId });
196	  callMod(st, ctx, 'fraud', oid, { op: 'start', orderId: oid, placedAt: st.placedAt, edition: st.edition });
197	  drainHeld(st, ctx);
198	}
199	
200	function fraudOut(out, st, ctx) {
201	  if (st.phase !== 'fraud') return;
202	  const oid = st.orderId;
203	  if (out.state === 'cleared') {
204	    st.clearedAt = out.at;
205	    if (st.fulfilments.some(f => !f.available)) {
206	      st.phase = 'waiting';                                                        // R3.1 starts
207	      callMod(st, ctx, 'customer-action', oid, { op: 'start', orderId: oid, placedAt: st.placedAt, clearedAt: out.at,
208	        edition: st.edition, fulfilments: st.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, available: f.available })) });
209	    } else {
210	      st.readyAt = out.at;                                                         // R4.1: ready at the clearing
211	      st.phase = 'processing';
212	    }
213	    drainHeld(st, ctx);
214	  } else if (out.state === 'cancel') {
215	    callMod(st, ctx, 'cancellation', oid, { op: 'cancel-order', orderId: oid, at: out.at, reason: out.reason });
216	    st.phase = 'ended';                                                            // S15
217	  }
218	}
219	
220	function customerActionOut(out, st, ctx) {
221	  if (st.phase !== 'waiting') return;
222	  if (out.state === 'ready') {
223	    st.readyAt = out.at;
224	    st.phase = 'processing';
225	  } else if (out.state === 'cancel') {
226	    callMod(st, ctx, 'cancellation', st.orderId, { op: 'cancel-order', orderId: st.orderId, at: out.at, reason: out.reason });
227	    st.phase = 'ended';                                                            // S15
228	  } else if (out.state === 'timedOut') {
229	    st.phase = 'ended';                                                            // R3.2: the end of the order
230	  }
231	}
232	
233	// R4.5: once a fulfilment has ended, the order is told; the order's own outcome comes back from order-progress.
234	function fulfilmentOut(fid, out, st, ctx) {
235	  if (!(out.end === 'completed' || out.end === 'failed') || st.ended[fid]) return;
236	  st.ended[fid] = out.end;
237	  if (st.phase !== 'processing') return;
238	  const r = callMod(st, ctx, 'order-progress', st.orderId, { op: 'ended', fulfilmentId: fid, end: out.end, at: out.endedAt });
239	  orderProgressOut(r, st);
240	}
241	
242	function orderProgressOut(out, st) {
243	  if (out.state === 'ended') {
244	    st.phase = 'ended';
245	    st.outcome = out.outcome;
246	  }
247	}
248	
249	// Forward steps (R3.1, R4.1, R4.2), once per transition, at the end of the tick (S10, S9).
250	function endOfTick(st, ctx) {
251	  const oid = st.orderId;
252	  if (st.phase === 'waiting') {
253	    const r = callMod(st, ctx, 'customer-action', oid, { op: 'advance' });
254	    customerActionOut(r, st, ctx);
255	  }
256	  if (st.phase === 'processing') {
257	    if (!st.progressReady) {
258	      st.progressReady = true;
259	      const fulfilments = st.fulfilments.map(f => ({ fulfilmentId: f.fulfilmentId, available: f.available }));
260	      orderProgressOut(callMod(st, ctx, 'order-progress', oid, { op: 'ready', orderId: oid, at: st.readyAt, fulfilments }), st);
261	    }
262	    for (const f of st.fulfilments) {
263	      if (st.phase !== 'processing' || !f.available || st.ended[f.fulfilmentId]) continue;
264	      const fid = f.fulfilmentId;
265	      if (!st.started[fid]) {
266	        st.started[fid] = true;
267	        callMod(st, ctx, 'fulfilment', fid, { op: 'start', orderId: oid, customerId: st.customerId, currency: st.currency,
268	          edition: st.edition, readyAt: st.readyAt,
269	          fulfilment: { fulfilmentId: fid, location: f.location, items: f.items, amountMinor: f.amountMinor } });
270	      }
271	      fulfilmentOut(fid, callMod(st, ctx, 'fulfilment', fid, { op: 'advance' }), st, ctx);
272	    }
273	  }
274	  if (st.phase === 'ended') {
275	    // Refresh the busy flags of every module that may still owe a result (the instance stays open until none does).
276	    callMod(st, ctx, 'statuses', oid, { op: 'get' });
277	    callMod(st, ctx, 'notices', oid, { op: 'get' });
278	    for (const fid of Object.keys(st.started)) {
279	      fulfilmentOut(fid, callMod(st, ctx, 'fulfilment', fid, { op: 'get' }), st, ctx);
280	    }
281	  }
282	}
283	
284	// §3.5: a migrated order continues from where it stands. Its own records (orders.*) say where that is.
285	function resumeMigration(ev, st, ctx) {
286	  // the migration payload carries the order; the first order-like reference in it names the case
287	  const found = (JSON.stringify(ev.payload ?? {}).match(/#?\s*ord-[\w-]+/i) ?? [null])[0];
288	  const oid = normalise(ev.payload?.orderId ?? ev.payload?.order?.orderId ?? found, ctx);
289	  if (!oid) return { subject: null, close: true };
290	  const ord = ctx.query('orders.orders', { where: { orderId: oid }, limit: 1 })[0];
291	  if (!ord) return { subject: oid, close: true };
292	  const rows = ctx.query('orders.fulfilments', { where: { orderId: oid }, limit: 1000 });
293	  st.orderId = oid;
294	  st.placedAt = ord.placedAt;
295	  st.customerId = ord.customerId;
296	  st.currency = ord.currency;
297	  st.fulfilments = rows.map(f => ({ fulfilmentId: f.fulfilmentId, location: f.location ?? null, available: f.status !== 'unavailable',
298	    items: f.items, amountMinor: f.amountMinor }));
299	  const intake = callMod(st, ctx, 'intake', oid, { op: 'resume', records: { intake: { order: { orderId: oid, customerId: ord.customerId,
300	    placedAt: ord.placedAt, currency: ord.currency, items: ord.items }, fulfilments: st.fulfilments, totalMinor: ord.totalMinor } } });
301	  st.edition = intake.edition ?? null;
302	  st.phase = 'fraud';
303	  if (['completed', 'failed', 'cancelled', 'timedOut'].includes(ord.status)) {
304	    st.phase = 'ended';
305	    st.outcome = ord.status;
306	    return { subject: oid, close: true };
307	  }
308	  if (ord.status === 'customerActionRequired') st.phase = 'waiting';
309	  else if (ord.status === 'processing') st.phase = 'processing';
310	  if (st.phase === 'processing') {
311	    st.readyAt = ord.placedAt;
312	    st.progressReady = true;
313	    for (const f of st.fulfilments) if (f.available) st.started[f.fulfilmentId] = true;
314	    callMod(st, ctx, 'order-progress', oid, { op: 'resume', records: { progress: { status: 'processing' } } });
315	  }
316	  return { subject: oid };
317	}
